record.field:
domain = []
if query:
    domain.append(('name', 'ilike', query))
if folder:
    domain.append(('folder_id.name', 'ilike', folder))
if mimetype:
    domain.append(('mimetype', 'ilike', mimetype))
docs = env['documents.document'].search(domain, limit=limit or 20)
lines = ['id|name|folder|mimetype|size|owner|create_date']
for d in docs:
    lines.append(f"{d.id}|{d.name}|{d.folder_id.name or ''}|{d.mimetype or ''}|{d.file_size or 0}|{d.owner_id.name or ''}|{d.create_date}")
ai['result'] = '\n'.join(lines)

{
    "type": "object",
    "properties": {
        "query": {
            "type": "string",
            "description": "Search by document name (partial match). Leave empty to list all."
        },
        "folder": {
            "type": "string",
            "description": "Filter by folder name (partial match). Optional."
        },
        "mimetype": {
            "type": "string",
            "description": "Filter by file type, e.g. 'pdf', 'xlsx', 'image'. Optional."
        },
        "limit": {
            "type": "integer",
            "description": "Maximum number of results (default 20)"
        }
    },
    "required": []
}

{
    "type": "object",
    "properties": {
        "document_id": {
            "type": "integer",
            "description": "The ID of the document to read (from Search Documents results)"
        }
    },
    "required": ["document_id"]
}
